+            this.user = user;
+            realmRef = null;
+            candidateAuthenticationTypes = EnumSet.of(AuthenticationType.INTERNAL);
+            return this;
+        }
+
+        public AuthenticationTestBuilder user(User user) {
+            if (User.isInternal(user)) {
+                return internal(user);
