+                        if (user == null) {
+                            user = randomUser();
+                        }
+                        if (realmRef == null) {
+                            realmRef = randomRealmRef(isRealmUnderDomain == null ? ESTestCase.randomBoolean() : isRealmUnderDomain);
+                        }
+                        assert false == SYNTHETIC_REALM_TYPES.contains(realmRef.getType()) : "use dedicate methods for synthetic realms";
