+                                if (user == null) {
+                                    user = randomUser();
+                                }
+                                prepareApiKeyMetadata();
+                                authentication = Authentication.newApiKeyAuthentication(
+                                    AuthenticationResult.success(user, metadata),
+                                    ESTestCase.randomAlphaOfLengthBetween(3, 8)
+                                ).token();
