+        private static final int CONSECUTIVE_DICTIONARY_WORDS_FOR_EXTRA_WEIGHT = 3;
+
+        private final CategorizationPartOfSpeechDictionary partOfSpeechDictionary;
+        private int consecutiveHighWeights;
