+
+        String newString3 = "the rock";
+        List<TokenAndWeight> newTokenIds3 = List.of(tw("the", 2), tw("rock", 2));
+        List<TokenAndWeight> newUniqueTokenIds3 = newTokenIds3.stream().sorted().distinct().collect(Collectors.toList());
